   tagged by RECORD_SOURCE and SOURCE_RUN. RECORD_SOURCE is NEVER in the key.
   KEY FORM: md5(upper('HUB_AGREEMENT|' || <business key>)), emitted EXPLICITLY -- no macro computes a
   hash in this build. The namespace is a MEASURED collision guard: opus_health_v2 emits
   md5(upper(HUB_ASSESSMENT_BK__SCRUTINY_NO)) AND md5(upper(HUB_PROPOSAL_BK__SCRUTINY_NO)),
   the same column under two hubs, which collide without it; legacy namespaces 1822 of 1822.
   CRITICAL PRECISION: the namespace separates HUBS, NOT REGISTRIES WITHIN A HUB.
   'HUB_POLICY|' prefixes POLICY_REF and POLICY_NO identically, so it does nothing to keep
   two identifier populations inside one hub apart.
   REGISTRY RECONCILIATION, UNRESOLVED: unifying the hash form does NOT establish that the
   two runs' identifier spaces denote the same entities. 6 of the 14 shared hubs have ZERO
   business-key-column overlap between the runs. This hub is ONE KEY SPACE over the
   registries enumerated below; a false merge is unrecoverable after load.
     opus_health_legacy_v4    3 registry/registries: HUB_AGREEMENT_BK__DEAL_ID, HUB_AGREEMENT_BK__HOSID, HUB_AGREEMENT_BK__REMEDINET_PROVIDER_CODE
   SINGLE-FEED: the settled map supplies columns from ONE run only for this
   table. Where both originals emit a file of this name, 'shared' is a
   property of the two FILE SETS, not of the map.
*/

with feeds as (
    select HUB_AGREEMENT_HK, HUB_AGREEMENT_BK__DEAL_ID as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_agreement__health_webservice_info__126648025b') }}
    union all
    select HUB_AGREEMENT_HK, HUB_AGREEMENT_BK__HOSID as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_agreement__hm_hospital_master__2e9263ab31') }}
    union all
    select HUB_AGREEMENT_HK, HUB_AGREEMENT_BK__HOSID as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_agreement__hm_hospital_master_extn__7f09c79e89') }}
    union all
    select HUB_AGREEMENT_HK, HUB_AGREEMENT_BK__HOSID as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_agreement__hm_hosp_master_extn1__48e0b9fc3f') }}
    union all
    select HUB_AGREEMENT_HK, HUB_AGREEMENT_BK__REMEDINET_PROVIDER_CODE as BUSINESS_KEY, RECORD_SOURCE, SOURCE_RUN, LOAD_DATETIME
    from {{ ref('hf_hub_agreement__remedinet_claim_details__0ccdf99cae') }}
)

select
    HUB_AGREEMENT_HK,
    BUSINESS_KEY,
    min(RECORD_SOURCE) as RECORD_SOURCE,
    min(SOURCE_RUN) as SOURCE_RUN,
    min(LOAD_DATETIME) as LOAD_DATETIME
from feeds
where HUB_AGREEMENT_HK is not null
group by HUB_AGREEMENT_HK, BUSINESS_KEY
